		/**
		 * Returns a new populated Catalog
		 * 
		 * @return Catalog
		 */
		protected Catalog generateNewEntity() {
			Catalog entity = new Catalog( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Boolean(true),  null,  new HashSet<>() );
			
			return( entity );
		}

